Let  $ M_{\phi}^{2} = M_{\chi}^{2} \equiv M^{2}$  and  $\gamma_{\phi} = \gamma_{\chi} \equiv \gamma$. Then  the solution to the coupled Klein--Gordon system \eqref{eq:CoupledKG} is
\begin{align} 
\begin{split}
    X(x) &= X_i - \beta(X_i) + \operatorname{Im} \bigl( u(x) \bigr), \\
    \Phi(x) &= \Phi_i - \tan(\Phi_i) + \operatorname{Re} \bigl( u(x) \bigr),
\end{split} \end{align} 
where
\begin{equation*}
    u(x) = C e^{-i(k+\gamma/2)x}{}_1F_1 \left( A; 3p; 2ikx \right)\,,
\end{equation*}
with $ k = \sqrt{ M^{2} + \dfrac{\gamma^{2}}{4} }$ and $A = \dfrac{3p}{2k} \left( k+\dfrac{\gamma}{2} \right)$. Here, $X_i$ and $\Phi_i$ represents the initial values of the fields $X$ and $\Phi$.

We use a source term of the form $Q=\lambda\dot{\chi}\dot{\phi}$~\cite{Garcia-Arroyo:2024tqq} which implies that the KG equations now become
\begin{align}
\label{kg1}
    &\ddot{\chi}+3H\dot{\chi}+\frac{\dd V_n(\chi)}{\dd\chi}=-\lambda\,\dot{\phi}\,, \\
    &\ddot{\phi}+3H\dot{\phi}+\frac{\dd V(\phi)}{\dd\phi}=\lambda\,\dot{\chi}\,,
\label{kg2}
\end{align}
where $\lambda>0$ is the coupling constant. 

For each respective field, we define the following dimensionless quantities:
\begin{align*}
        &\Phi\equiv\phi/f, ~\quad m_\phi\equiv \Lambda^2_\phi/f, ~\quad \alpha_\phi\equiv f/M_p, \quad ~x\equiv H_0 t, \quad \text{and} \quad \mu_\phi\equiv m_\phi/H_0, \\
        &X\equiv \chi/F, \quad m_\chi\equiv \Lambda^2_\chi/F, \quad \alpha_\chi\equiv F/M_p, \quad ~x\equiv H_0 t, \quad \text{and} \quad \mu_\chi\equiv m_\chi/H_0,
    \end{align*}
These changes in variables morph \eqref{kg1} into
\begin{equation}
    X^{\prime\prime}+3\frac{p}{x}X^\prime+\alpha_\chi^{-2}\frac{\dd V_n(X)}{\dd X}=-\lambda\frac{\alpha_\phi}{\alpha_\chi}\Phi^\prime,
    \label{Dless kg1}
\end{equation}
and \eqref{kg2} into
\begin{equation}
    \Phi^{\prime\prime}+3\frac{p}{x}\Phi^\prime+\alpha^{-2}_\phi\frac{\dd V(\Phi)}{\dd\Phi}=\lambda\frac{\alpha_\chi}{\alpha_\phi}X^\prime.
    \label{Dless kg2}
\end{equation}
As usual, the primes represent derivatives with respect to the independent variable $x$.
We continue by finding the derivatives of the potentials in \eqref{p1} and \eqref{p2},
\begin{align*}
\frac{\dd V(\Phi)}{\dd\Phi} &= -\mu_\phi^{2}\alpha_\phi^{2}\sin{\Phi}, \\
\frac{\dd^2V(\Phi)}{\dd\Phi^2} &= -\mu_\phi^{2}\alpha_\phi^{2}\cos{\Phi}, \\
\frac{\dd V_n(X)}{\dd X} &= \mu_\chi^{2}\alpha_\chi^{2}n\sin{X}(1-\cos{X})^{n-1}, \\
\frac{\dd^2 V_n(X)}{\dd X^2} &= \mu_\chi^{2}\alpha_\chi^{2}n(n-1)\sin^2{X}(1-\cos{X})^{n-2}+\mu_\chi^{2}\alpha_\chi^{2}n\cos{X}(1-\cos{X})^{n-1} \\
&= \frac{\dd V_n(X)}{\dd X}\left(\frac{n+n\cos{X}-1}{\sin{X}}\right).  
\end{align*}
After an expansion of the potentials around their initial values $X_i~\text{and}~\Phi_i$, we get
\begin{equation*}
    \frac{\dd V(\Phi_i)}{\dd\Phi} \approx \frac{\dd^2 V(\Phi_i)}{\dd\Phi^2}(\tan{\Phi_i}+\delta\Phi)\,,
\end{equation*}
and
\begin{equation*}
    \frac{\dd V_n(X_i)}{\dd X} \approx \frac{\dd^2V_n(X_i)}{\dd X^2} \left(\frac{\sin{X_i}}{n+n\cos{X_i}-1}+\delta X\right).
\end{equation*}
Here, $\delta\Phi = \Phi-\Phi_i$ and $\delta X=X-X_i$. Now \eqref{Dless kg1} and \eqref{Dless kg2} become
\begin{equation*}
\delta X^{\prime\prime}+3\frac{p}{x}\delta X^\prime+\alpha_\chi^{-2}\frac{\dd^2V_n(X_i)}{\dd X^2}\left(\frac{\sin{X_i}}{n+n\cos{X_i}-1}+\delta X\right) = -\gamma_\chi\delta\Phi^\prime \,,
\end{equation*}
and
\begin{equation*}
\delta\Phi^{\prime\prime}+3\frac{p}{x}\delta\Phi^\prime+\alpha_\phi^{-2}\frac{\dd^2V(\Phi_i)}{\dd\Phi^2}(\tan{\Phi_i}+\delta\Phi) = \gamma_\phi\delta\chi^\prime\,,
\end{equation*}
where we have defined the interaction terms as
\begin{equation}
\gamma_\chi \equiv \lambda\frac{\alpha_\phi}{\alpha_\chi}\,, \quad \text{and} \quad \gamma_\phi\equiv\lambda\frac{\alpha_\chi}{\alpha_\phi}\,.    
\label{gammaint}
\end{equation}
We define the mass terms
\begin{align*}
M_\chi^2 &\equiv \alpha_\chi^{-2}\frac{\dd^2V_n(X_i)}{\dd X^2},\\
M_\phi^2 &\equiv \alpha_\phi^{-2}\frac{\dd^2V(\Phi_i)}{\dd\Phi^2},
\end{align*}
and the new variables
\begin{align*}
y_\chi(x) &=\delta X +\frac{\sin{X_i}}{n+n\cos{X_i}-1}\,, \\
y_\phi(x)&= \delta\Phi+\tan{\Phi_i}\,,    
\end{align*}
which allows us to cast the differential equations in the forms
\begin{equation}
    y_\phi^{\prime\prime}+3\frac{p}{x}y^\prime_\phi+M_\phi^2 y_\phi=\gamma_\phi y_\chi^\prime\,,
    \label{yphi}
\end{equation}
and
\begin{equation}
y_\chi^{\prime\prime}+3\frac{p}{x}y^\prime_\chi+M_\chi^2 y_\chi=-\gamma_\chi y_\phi^\prime\,.
\label{ychi}
\end{equation}
 We then define a complex-valued function $u(x) =y_\phi(x) +i\,y_\chi(x)$, where $i$ is the imaginary unit. Under our assumptions $M_\phi^2=M_\chi^2\equiv M^2,~\text{and}~\gamma_\phi=\gamma_\chi\equiv\gamma$, multiplying \eqref{ychi} by the imaginary unit $i$ and adding to \eqref{yphi} results in 
\begin{equation}
u''+\left(3\frac{p}{x}+i\gamma\right)u'+M^2u=0.
\label{ueq}
\end{equation}
The hypergeometric function of the first kind $_1F_1(A;b;z)$ satisfies~(\ref{eq:kummer}). We turn \eqref{ueq} into the form of Kummer's equation, \eqref{eq:kummer}, by letting 
\begin{equation*}
u = e^{i\kappa x}f(z(x))\,,    
\end{equation*}
with $z(x)=\xi x^n$, and where $\kappa$, $\xi$ and $n$ are constants to be determined. Then
\begin{align*}
u^\prime&=e^{i\kappa x}\frac{\dd f}{\dd z}\frac{\dd z}{\dd x}+i\kappa e^{i\kappa x}f(z)\,, \\
u^{\prime\prime}&=e^{i\kappa x}\frac{\dd^2 f}{\dd z^2}\left(\frac{\dd z}{\dd x}\right)^2+2i\kappa e^{i\kappa x}\frac{\dd f}{\dd z}\frac{\dd z}{\dd x}-\kappa^2 e^{i\kappa x}f(z).
\end{align*}
Substituting $u^\prime$ and $u^{\prime\prime}$ into \eqref{ueq} gives
\begin{align}
&\frac{\dd^2 f}{\dd z^2}\xi^2 n^2 x^{2(n-1)}+\frac{\dd f}{\dd z}\left[\xi n(n-1)x^{n-2}+\xi n x^{n-1}\left(3\frac{p}{x}+2i\kappa+i\gamma\right)\right] \nonumber \\
&\hspace{9.67cm}+\left(M^2+3\frac{p}{x}i\kappa-\gamma \kappa-\kappa^2\right)f=0 \nonumber \\
&\frac{\dd^2 f}{\dd z^2}\xi^2 n^2 x^{2(n-1)}+\frac{\dd f}{\dd z}\xi nx^{n-2}\big(n-1+3p+2i\kappa x+i\gamma x\big)+\left(M^2+3\frac{p}{x}i\kappa-\gamma \kappa-\kappa^2\right)f=0 \nonumber \\
&\frac{\dd^2 f}{\dd z^2} \xi x^n+\frac{\dd f}{\dd z}(n-1+3p+2i\kappa x+i\gamma x)+ \frac{x^{1-n}}{\xi n}\Big[(M^2-\gamma \kappa-\kappa^2)x+3ip\kappa\Big]f=0\,.
\label{eqf}
\end{align}
We extract the values for $n$, $\kappa$ and $\xi$ such that \eqref{eqf} takes the form of \eqref{eq:kummer}. We begin by observing that $M^2-\gamma \kappa-\kappa^2$ must vanish, that is,
\begin{equation*}
M^2-\gamma \kappa-\kappa^2=0 \quad\text{ or }\quad \kappa=-\frac{\gamma}{2}\mp \sqrt{M^2+\frac{\gamma^2}{4}}\equiv -\frac{\gamma}{2}\mp k\,.
\end{equation*}
We choose the negative root of $\kappa$ and by setting $n=1$, we get
\begin{align*}
\xi x\frac{\dd^2 f}{\dd z^2}+(3p-2ikx)\frac{\dd f}{\dd z}-i\frac{3p}{\xi}\left(\frac{\gamma}{2}+k\right)f&=0.
\end{align*}
Finally, by letting $\xi \equiv 2ik$, we arrive at
\begin{align}
z\frac{\dd^2 f}{\dd z^2}+(3p-z)\frac{\dd f}{\dd z}-\frac{3p}{2k}\left(\frac{\gamma}{2}+k\right)f&=0\,.
\label{coupled_solution}
\end{align}
We can identify from \eqref{coupled_solution} and \eqref{eq:kummer} that 
\begin{equation*}
b\equiv 3p\,, \quad \text{and} \quad A\equiv \frac{3p}{2k}\left(\frac{\gamma}{2}+k\right)\,.
\end{equation*}
Therefore, the general solution is
\begin{equation*}
f(z) = C_1\, {}_1F_1(A;3p;z) + C_2\, U(A;3p;z)\,,
\end{equation*}
where $U(A;3p;z)$ is the Tricomi function~(\ref{eq:tricomi}). 
Hence
\begin{equation*}
u(x)=e^{-i\left(k+\gamma/2\right)x}\Big[C_1\,{}_1F_1\!\left(A;3p;2ikx\right)+C_2\, U\!\left(A;3p;2ikx\right)\Big].
\end{equation*}
Imposing regularity at the origin eliminates the Tricomi function $U(A;3p;2ikx)$ which blows up when $x\to 0$. The function ${}_1F_1(A;3p;2ikx)\to 1$ as $x\to 0$. Therefore, the regular solution is
\begin{equation*}
u(x)=C\,e^{-i\left(k+\gamma/2\right)x}\,{}_1F_1\!\left(A;3p;2ikx\right)\,,
\end{equation*}
where $C=K_1+iK_2$.  
The two real fields are then
\begin{align}
y_\chi(x) &= \Im\!\bigl[u(x)\bigr]=\beta(X_i)+\delta X=\beta(X_i)+X-X_i\,, \\
y_\phi(x) &= \Re\!\bigl[u(x)\bigr]=\tan\Phi_i+\delta\Phi=\tan\Phi_i+\Phi-\Phi_i\,.
\end{align}
The real constants of integration $K_1$ and $K_2$ can be determined from initial conditions: at $x=0$, $X=X_i$ and $\Phi=\Phi_i$, so for $X$, we get $K_2=\beta(X_i)$ and for $\Phi$ we get $K_1=\tan\Phi_i$. Therefore, the function $u(x)$ becomes
\begin{equation*}
u(x)=\Big[\tan\Phi_i+i\beta(X_i)\Big]\,e^{-i\left(k+\gamma/2\right)x}\,{}_1F_1\!\left(A;3p;2ikx\right)\,,
\end{equation*}
and our dark matter and dark energy fields evolve as
\begin{align}
\label{eq:xfinal}
X(x)&=X_i-\beta(X_i)+\Im\!\bigl[u(x)\bigr]\,, \\
\Phi(x)&=\Phi_i-\tan\Phi_i+\Re\!\bigl[u(x)\bigr]\,.
\label{eq:phifinal}
\end{align}
where
\begin{align}
    \beta(X_i)&=\frac{\sin X_i}{n+n\cos X_i-1}\,.
    \label{beta}
\end{align}
